-- 0034_seed_oratory_course.sql — онлайн-курс «Ораторское искусство» (черновик)
--
-- Создаёт курс с описанием, «чему научитесь», 14 наградами и 20 уроками
-- (теория, упражнения, тесты, карточки, опыт навыкам; финалы глав отмечены).
-- Видео в уроках пустые — добавьте ссылки YouTube в «Редакторе курсов».
-- Курс создаётся НЕОПУБЛИКОВАННЫМ: проверьте, поправьте и включите «Опубликован».
-- Цену и ссылку на оплату тоже задайте в редакторе.
--
-- Применить: Supabase → SQL Editor → вставить → Run. ПОСЛЕ 0033.
-- Повторный запуск обновляет описание и награды курса, а уроки создаёт заново
-- (не запускайте повторно, когда курс уже проходят ученики — собьётся прогресс).

insert into public.online_courses (id, title, direction, summary, description, outcomes, awards, published, sort)
values ('a7a0c0de-0000-4000-8000-000000000001', $t$Ораторское искусство$t$, 'acting', $t$Говори так, чтобы слушали. Голос, уверенность и умение держать внимание зала — за 5 глав с упражнениями и обратной связью педагога.$t$,
  $t$Страх выступать — самый частый страх у детей и взрослых. Хорошая новость: публичная речь — это навык, а не врождённый талант, и его можно натренировать, как мышцу.

Курс ведёт Антон Шпигоцкий — актёр Областного драматического театра им. Н. Погодина, выпускник Высшего театрального училища им. М. С. Щепкина. В основе — театральная школа: дыхание, голос, сценическое поведение и работа с текстом, то есть те же инструменты, которыми пользуются профессиональные актёры.

Как проходит обучение: 5 глав по 4 урока — короткое видео, теория, практическое упражнение и мини-тест. В конце каждой главы — испытание: вы записываете выступление на видео и отправляете педагогу. Карточки для повторения закрепляют ключевые приёмы. Свой темп: 10–15 минут в день.

Для кого: школьники от 10 лет, подростки и взрослые — все, кто волнуется у доски, готовится к защите проекта, конкурсу, собеседованию или просто хочет говорить увереннее.

Результат: вы спокойно выходите к слушателям, говорите ясно и громко, держите внимание и умеете выстроить речь от первой фразы до финала. В конце курса — именной сертификат студии.$t$,
  array[$t$Управлять волнением и превращать его в энергию выступления$t$, $t$Правильно дышать: голос звучит сильно и не дрожит$t$, $t$Говорить чётко и разборчиво$t$, $t$Держать позу, жесты и взгляд уверенно$t$, $t$Выделять главное паузами, логическим ударением и интонацией$t$, $t$Выразительно читать стихи и прозу$t$, $t$Строить выступление: яркое начало, ясная середина, запоминающийся финал$t$, $t$Удерживать внимание слушателей и отвечать на вопросы$t$, $t$Импровизировать и не теряться, если что-то пошло не так$t$, $t$Выступать перед аудиторией 3 минуты без бумажки$t$]::text[],
  $j$[{"id": "warmup", "title": "Разогрев", "desc": "Пройти первый урок", "icon": "play", "rule": {"type": "lessons", "n": 1}}, {"id": "first_sound", "title": "Первый звук", "desc": "Сдать первое задание", "icon": "doc", "rule": {"type": "homework", "n": 1}}, {"id": "tongue", "title": "Скороговорщик", "desc": "Сдать 5 заданий", "icon": "spark", "rule": {"type": "homework", "n": 5}}, {"id": "dictionary", "title": "Словарь оратора", "desc": "Выучить 10 карточек", "icon": "doc", "rule": {"type": "cards", "n": 10}}, {"id": "practitioner", "title": "Практик", "desc": "Сдать 10 заданий", "icon": "flame", "rule": {"type": "homework", "n": 10}}, {"id": "first_trial", "title": "Первое испытание", "desc": "Пройти первый финал главы", "icon": "trophy", "rule": {"type": "boss"}}, {"id": "ch1", "title": "Голос найден", "desc": "Пройти главу 1 «Голос и дыхание»", "icon": "star", "rule": {"type": "lessons", "n": 4}}, {"id": "ch2", "title": "Смелый выход", "desc": "Пройти главу 2 «Уверенность и тело»", "icon": "star", "rule": {"type": "lessons", "n": 8}}, {"id": "ch3", "title": "Смысл в каждом слове", "desc": "Пройти главу 3 «Текст и смысл»", "icon": "star", "rule": {"type": "lessons", "n": 12}}, {"id": "ch4", "title": "Архитектор речи", "desc": "Пройти главу 4 «Строим выступление»", "icon": "star", "rule": {"type": "lessons", "n": 16}}, {"id": "word_master", "title": "Мастер слова", "desc": "Выучить 30 карточек", "icon": "spark", "rule": {"type": "cards", "n": 30}}, {"id": "tireless", "title": "Неутомимый", "desc": "Сдать все 20 заданий курса", "icon": "flame", "rule": {"type": "homework", "n": 20}}, {"id": "sharp_mind", "title": "Острый ум", "desc": "Все тесты курса без ошибок", "icon": "check", "rule": {"type": "quiz_perfect"}}, {"id": "orator", "title": "Оратор", "desc": "Пройти весь курс", "icon": "trophy", "rule": {"type": "complete"}}]$j$::jsonb,
  false, 10)
on conflict (id) do update set
  title = excluded.title, direction = excluded.direction, summary = excluded.summary,
  description = excluded.description, outcomes = excluded.outcomes, awards = excluded.awards,
  updated_at = now();

delete from public.online_lessons where course_id = 'a7a0c0de-0000-4000-8000-000000000001';

insert into public.online_lessons (course_id, sort, title, free, content) values
  ('a7a0c0de-0000-4000-8000-000000000001', 0, $t$Глава 1 · Урок 1. Знакомство: зачем учиться говорить$t$, true,
   $j${"yt": "", "desc": "Разбираемся, почему выступать страшно и почему это нормально. Ставим личную цель курса.", "theory": "Страх публичных выступлений — один из самых распространённых страхов. Его испытывают и дети, и взрослые, и даже опытные артисты. Хорошая новость: уверенная речь — навык, а не врождённый талант. Как в спорте, его развивают регулярные короткие тренировки и обратная связь. На курсе мы идём от простого к сложному: голос и дыхание → тело и уверенность → текст и смысл → построение речи → живой контакт с залом.", "practice": "Запишите себе (или на видео) ответы: где вам нужно выступать? Что больше всего пугает? Каким оратором вы хотите стать через 2 месяца? Сформулируйте цель одной фразой, например: «Спокойно рассказать доклад перед классом».", "skills": {"Раскрепощённость": 20, "Сценическая речь": 5}, "quiz": [{"q": "Уверенная речь — это…", "options": ["Врождённый талант", "Навык, который развивается тренировкой", "Удача"], "correct": 1}, {"q": "Что быстрее всего помогает расти?", "options": ["Регулярная практика и обратная связь", "Ждать вдохновения", "Только читать книги об ораторах"], "correct": 0}], "cards": [{"front": "Публичная речь", "back": "Навык: тренируется короткими регулярными упражнениями и обратной связью"}, {"front": "Цель курса", "back": "Конкретный результат, к которому вы идёте: «выступить на защите проекта без страха»"}]}$j$::jsonb),
  ('a7a0c0de-0000-4000-8000-000000000001', 1, $t$Глава 1 · Урок 2. Дыхание — опора голоса$t$, false,
   $j${"yt": "", "desc": "Учимся дышать «животом»: так голос звучит сильно и не дрожит от волнения.", "theory": "Когда мы волнуемся, дыхание становится поверхностным — грудным. Голосу не хватает воздуха, он дрожит и садится. Ораторы и актёры дышат иначе: вдох идёт в нижнюю часть лёгких, живот слегка выдвигается вперёд, плечи не поднимаются. Главная мышца такого дыхания — диафрагма. На ровном, долгом выдохе и держится звук — это называют «опорой дыхания».", "practice": "Упражнение «Свеча»: положите ладонь на живот, сделайте спокойный вдох носом (живот вперёд, плечи на месте) и медленно выдыхайте на «ффф», как будто колышете пламя свечи, но не гасите его. 5 подходов. Засеките, сколько секунд длится ровный выдох, и запишите результат — через неделю сравним.", "skills": {"Сценическая речь": 20, "Раскрепощённость": 5}, "quiz": [{"q": "Куда идёт вдох при правильном дыхании?", "options": ["В плечи", "В нижнюю часть лёгких, живот чуть вперёд", "В горло"], "correct": 1}, {"q": "Как называют ровный выдох, на котором держится звук?", "options": ["Опора дыхания", "Задержка", "Распевка"], "correct": 0}, {"q": "Почему от волнения дрожит голос?", "options": ["Дыхание становится поверхностным", "Слишком громко говорим", "Устали связки"], "correct": 0}], "cards": [{"front": "Диафрагма", "back": "Главная дыхательная мышца; при вдохе опускается, и живот чуть выдвигается вперёд"}, {"front": "Опора дыхания", "back": "Ровный, управляемый выдох, на котором звучит голос"}]}$j$::jsonb),
  ('a7a0c0de-0000-4000-8000-000000000001', 2, $t$Глава 1 · Урок 3. Дикция: говорим чётко$t$, false,
   $j${"yt": "", "desc": "Разминаем речевой аппарат: губы, язык, челюсть — и избавляемся от «каши во рту».", "theory": "Дикция — это ясное, чёткое произношение звуков. Её делают губы, язык и нижняя челюсть, и, как любые мышцы, их можно разогреть и натренировать. Актёры перед спектаклем всегда делают артикуляционную гимнастику. Скороговорки читают сначала медленно и очень чётко, и только потом ускоряются: скорость без чёткости бесполезна.", "practice": "Артикуляционная разминка 3 минуты: «трубочка — улыбка» 10 раз, «часики» языком 10 раз, «лошадка» (цоканье) 10 раз. Затем скороговорка «Шла Саша по шоссе и сосала сушку»: 3 раза медленно и чётко, 3 раза в среднем темпе, 3 раза быстро. Запишите на видео последний подход.", "skills": {"Сценическая речь": 25}, "quiz": [{"q": "С какой скоростью начинать скороговорку?", "options": ["Сразу быстро", "Медленно и чётко, потом ускоряться", "Шёпотом"], "correct": 1}, {"q": "Что такое дикция?", "options": ["Громкость голоса", "Ясное, чёткое произношение звуков", "Красивые слова"], "correct": 1}], "cards": [{"front": "Дикция", "back": "Ясное, чёткое произношение каждого звука"}, {"front": "Артикуляционная гимнастика", "back": "Разминка губ, языка и челюсти перед выступлением"}]}$j$::jsonb),
  ('a7a0c0de-0000-4000-8000-000000000001', 3, $t$Глава 1 · Финал. «Первое слово»$t$, false,
   $j${"yt": "", "desc": "Испытание главы: короткое видео-приветствие с правильным дыханием и чёткой речью.", "theory": "Перед записью: 3 спокойных вдоха «животом», короткая артикуляционная разминка. Смотрите в камеру, как в глаза другу. Первую фразу говорите медленно — так вы задаёте спокойный темп всей речи.", "practice": "Запишите видео до 30 секунд: «Здравствуйте! Меня зовут… Я учусь ораторскому искусству, потому что…». Напишите в отчёте, что получилось и что было сложно, и отправьте видео педагогу.", "skills": {"Сценическая речь": 20, "Раскрепощённость": 20}, "boss": true}$j$::jsonb),
  ('a7a0c0de-0000-4000-8000-000000000001', 4, $t$Глава 2 · Урок 5. Волнение — твой союзник$t$, false,
   $j${"yt": "", "desc": "Учимся не бороться с волнением, а направлять его энергию в выступление.", "theory": "Волнение — это энергия: учащённое сердцебиение и бодрость готовят организм к важному делу. Задача оратора — не убрать волнение, а управлять им. Работают три приёма: дыхание (длинный выдох успокаивает), подготовка (чем лучше знаешь текст, тем меньше страх) и переключение внимания с себя на слушателей: «я здесь, чтобы помочь им понять».", "practice": "Перед любым ответом у доски или разговором этой недели сделайте «квадратное дыхание»: вдох на 4 счёта, задержка 4, выдох 4, пауза 4 — 3 круга. Опишите в отчёте, в какой ситуации попробовали и что почувствовали.", "skills": {"Раскрепощённость": 25}, "quiz": [{"q": "Что такое волнение перед выступлением?", "options": ["Признак, что ты не готов", "Энергия, которой можно управлять", "Болезнь"], "correct": 1}, {"q": "Какой выдох помогает успокоиться?", "options": ["Короткий и резкий", "Длинный и ровный", "Любой"], "correct": 1}], "cards": [{"front": "Квадратное дыхание", "back": "Вдох 4 счёта — задержка 4 — выдох 4 — пауза 4; успокаивает перед выступлением"}, {"front": "Фокус на слушателях", "back": "Думать не «как я выгляжу», а «что важно понять залу» — снижает страх"}]}$j$::jsonb),
  ('a7a0c0de-0000-4000-8000-000000000001', 5, $t$Глава 2 · Урок 6. Поза и опора$t$, false,
   $j${"yt": "", "desc": "Как стоять перед слушателями, чтобы чувствовать и выглядеть уверенно.", "theory": "Тело влияет на состояние: когда мы стоим ровно и устойчиво, нам и самим спокойнее. Опорная поза оратора: стопы на ширине плеч, вес распределён на обе ноги, колени не зажаты, плечи расправлены и опущены, макушка тянется вверх. Не раскачивайтесь, не переминайтесь с ноги на ногу, не прячьте руки за спину и в карманы.", "practice": "Встаньте перед зеркалом в опорную позу и простойте 1 минуту молча, глядя себе в глаза. Затем скажите в этой позе: «Добрый день! Сегодня я расскажу вам о…». Снимите короткое видео.", "skills": {"Раскрепощённость": 20, "Сценическая речь": 5}, "quiz": [{"q": "Как стоять перед слушателями?", "options": ["Переминаясь с ноги на ногу", "Устойчиво: стопы на ширине плеч, вес на обе ноги", "Опираясь на стол"], "correct": 1}, {"q": "Куда деть руки в начале выступления?", "options": ["В карманы", "За спину", "Свободно перед собой, готовы к жесту"], "correct": 2}], "cards": [{"front": "Опорная поза", "back": "Стопы на ширине плеч, вес на обе ноги, плечи опущены, макушка тянется вверх"}, {"front": "Закрытые позы", "back": "Руки за спиной, в карманах, скрещены — выглядят неуверенно"}]}$j$::jsonb),
  ('a7a0c0de-0000-4000-8000-000000000001', 6, $t$Глава 2 · Урок 7. Жесты и взгляд$t$, false,
   $j${"yt": "", "desc": "Учимся помогать словам руками и держать контакт глазами со всем залом.", "theory": "Жест должен помогать смыслу: показать размер, направление, перечисление. Работают жесты в зоне от пояса до плеч, открытые ладони вызывают доверие. Взгляд — главный способ контакта. Правило «острова»: разделите зал на зоны и задерживайте взгляд на одном человеке в каждой зоне 2–3 секунды, на целую мысль.", "practice": "Расскажите домашним (или на камеру) короткую историю «Как прошёл мой день», используя минимум 3 осмысленных жеста и переводя взгляд с одного слушателя на другого. Попросите оценить, было ли интересно.", "skills": {"Раскрепощённость": 20, "Сценическая речь": 5}, "quiz": [{"q": "Где лучше всего работают жесты?", "options": ["Ниже пояса", "От пояса до плеч", "Над головой"], "correct": 1}, {"q": "Сколько держать взгляд на одном слушателе?", "options": ["Не смотреть на людей", "2–3 секунды, на целую мысль", "Всё выступление"], "correct": 1}], "cards": [{"front": "Открытые ладони", "back": "Жест, который вызывает доверие слушателей"}, {"front": "Правило «острова»", "back": "Делим зал на зоны и смотрим на одного человека в каждой 2–3 секунды"}]}$j$::jsonb),
  ('a7a0c0de-0000-4000-8000-000000000001', 7, $t$Глава 2 · Финал. «Выход на сцену»$t$, false,
   $j${"yt": "", "desc": "Испытание главы: правильный выход, пауза и уверенное представление себя.", "theory": "Сильное начало — до первого слова. Выйдите спокойным шагом, встаньте в опорную позу, сделайте паузу 2 секунды и посмотрите на слушателей. И только потом — первая фраза.", "practice": "Запишите видео до 1 минуты: выход в кадр, пауза, представление себя (имя, увлечения, одна интересная деталь о вас) с жестами и взглядом в камеру. Опишите в отчёте, что получилось, и отправьте видео педагогу.", "skills": {"Раскрепощённость": 25, "Сценическая речь": 15}, "boss": true}$j$::jsonb),
  ('a7a0c0de-0000-4000-8000-000000000001', 8, $t$Глава 3 · Урок 9. Паузы$t$, false,
   $j${"yt": "", "desc": "Пауза — главный инструмент оратора: она держит внимание и придаёт словам вес.", "theory": "Логическая пауза отделяет смысловые части фразы: «Казнить нельзя / помиловать». От места паузы меняется смысл! Психологическая пауза — более длинная остановка перед важной мыслью или после неё: она создаёт напряжение и даёт слушателям осмыслить сказанное. Новички боятся пауз и заполняют их «э-э-э». Опытные ораторы делают паузы смело.", "practice": "Возьмите абзац из любой книги и расставьте карандашом паузы: «/» — короткая, «//» — длинная. Прочитайте вслух дважды: без пауз и с паузами. Запишите на видео второй вариант.", "skills": {"Работа с текстом": 25}, "quiz": [{"q": "Что изменится, если перенести паузу во фразе «Казнить нельзя помиловать»?", "options": ["Ничего", "Смысл фразы", "Только громкость"], "correct": 1}, {"q": "Чем лучше заполнить паузу?", "options": ["Словом «э-э-э»", "Тишиной", "Покашливанием"], "correct": 1}], "cards": [{"front": "Логическая пауза", "back": "Короткая остановка, отделяющая смысловые части фразы"}, {"front": "Психологическая пауза", "back": "Длинная пауза перед или после важной мысли — создаёт напряжение и вес"}]}$j$::jsonb),
  ('a7a0c0de-0000-4000-8000-000000000001', 9, $t$Глава 3 · Урок 10. Логическое ударение$t$, false,
